create or replace function public.ff_match_create(
  p_league uuid, p_gameweek uuid, p_team_a uuid, p_team_b uuid, p_organizer uuid,
  p_starts_at timestamptz, p_venue text, p_starters_per_side integer default 7,
  p_max_substitutes integer default 5)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare v public.real_matches;
begin
  perform ff_private.require_leader(p_league);
  if p_team_a is null or p_team_b is null or p_team_a = p_team_b then
    raise exception 'choose two different teams' using errcode='23514';
  end if;
  if not exists (select 1 from public.match_organizers o join public.league_members lm
      on lm.league_id=o.league_id and lm.user_id=o.user_id
      where o.league_id=p_league and o.user_id=p_organizer and lm.status='active') then
    raise exception 'organizer must be an active appointed match organizer' using errcode='23514';
  end if;
  if p_gameweek is not null and not exists (
    select 1 from public.gameweeks where league_id=p_league and id=p_gameweek
  ) then
    raise exception 'gameweek not found' using errcode='23514';
  end if;
  if not exists (select 1 from public.real_football_teams where league_id=p_league and id=p_team_a and active)
     or not exists (select 1 from public.real_football_teams where league_id=p_league and id=p_team_b and active) then
    raise exception 'both active teams must belong to this league' using errcode='42501';
  end if;
  if p_starts_at is null then raise exception 'a match needs a kick-off time' using errcode='23514'; end if;
  if p_venue is null or length(btrim(p_venue))=0 or length(btrim(p_venue))>200 then
    raise exception 'venue is required and must be at most 200 characters' using errcode='23514';
  end if;
  if coalesce(p_starters_per_side,0) not between 1 and 11 or coalesce(p_max_substitutes,-1) not between 0 and 30 then
    raise exception 'starters must be 1–11 and substitutes 0–30' using errcode='23514';
  end if;
  insert into public.real_matches(league_id,gameweek_id,team_a_id,team_b_id,organizer_id,starts_at,venue,starters_per_side,max_substitutes)
  values(p_league,p_gameweek,p_team_a,p_team_b,p_organizer,p_starts_at,btrim(p_venue),p_starters_per_side,p_max_substitutes)
  returning * into v;
  perform ff_private.audit(p_league,'match_created','match',v.id,
    jsonb_build_object('gameweek_id',p_gameweek,'team_a',p_team_a,'team_b',p_team_b));
  return jsonb_build_object('id',v.id,'starts_at',v.starts_at,'organizer_id',p_organizer);
end $$;

